// Linux port (vos-splash): the boot loader platform layer (kernel_args,
// platform_set_palette(), platform_blit4()) is replaced by the frame buffer
// that splash_display.cpp maps; the drawing below is the boot loader's.

#include <boot/platform/generic/video_blitter.h>

#include <splash_images.h>
	// generated by CMake: includes the air/OS image header, never Haiku's
#include <boot/platform/generic/video_splash.h>

#include "splash_platform.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <zlib.h>


//#define TRACE_VIDEO
