static status_t
uncompress(const uint8 compressed[], unsigned int compressedSize,
	uint8* uncompressed, unsigned int uncompressedSize)
{
	if (compressedSize == 0 || uncompressedSize == 0)
		return B_BAD_VALUE;

	// prepare zlib stream
	z_stream zStream = {
		(Bytef*)compressed,		// next_in
		compressedSize,			// avail_in
		0,						// total_in
		(Bytef*)uncompressed,	// next_out
		uncompressedSize,		// avail_out
		0,						// total_out
		0,						// msg
		0,						// state
		Z_NULL,					// zalloc (kernel_args_malloc?)
		Z_NULL,					// zfree (kernel_args_free?)
		Z_NULL,					// opaque
		0,						// data_type
		0,						// adler
		0						// reserved
	};

	int zlibError = inflateInit(&zStream);
	if (zlibError != Z_OK)
		return B_ERROR;	// TODO: translate zlibError

	// inflate
	status_t status = B_OK;
	zlibError = inflate(&zStream, Z_FINISH);
	if (zlibError != Z_STREAM_END) {
		if (zlibError == Z_OK)
			status = B_BUFFER_OVERFLOW;
		else
			status = B_ERROR;	// TODO: translate zlibError
	}

	// clean up
	zlibError = inflateEnd(&zStream);
	if (zlibError != Z_OK && status == B_OK)
		status = B_ERROR;	// TODO: translate zlibError

	if (status == B_OK && zStream.total_out != uncompressedSize)
		status = B_ERROR;

	return status;
}


void (*video_set_palette)(const uint8* palette) = NULL;


status_t
video_uncompress_image(const uint8* compressed, unsigned int compressedSize,
	uint8* uncompressed, unsigned int uncompressedSize)
{
	return uncompress(compressed, compressedSize, uncompressed,
		uncompressedSize);
}


void
video_blit_image(const splash_frame_buffer& frameBuffer, const uint8 *data,
	uint16 width, uint16 height, uint16 imageWidth, uint16 left, uint16 top)
{
	// The boot loader's 4 bit VGA path (platform_blit4()) has no Linux
	// equivalent: neither DRM dumb buffers nor fbdev offer planar modes.
	// Nor did it draw on screens too small for the image: skip those.
	if ((uint32)left + width > frameBuffer.width
		|| (uint32)top + height > frameBuffer.height)
		return;

	BlitParameters params;
	params.from = data;
	params.fromWidth = imageWidth;
	params.fromLeft = params.fromTop = 0;
	params.fromRight = width;
	params.fromBottom = height;
	params.to = frameBuffer.frame_buffer;
	params.toBytesPerRow = frameBuffer.bytes_per_row;
	params.toLeft = left;
	params.toTop = top;
	blit(params, frameBuffer.depth);
}


void
video_splash_logo_size(uint16* width, uint16* height)
{
	*width = kSplashLogoWidth;
	*height = kSplashLogoHeight;
}


void
video_splash_icons_size(uint16* width, uint16* height)
{
	*width = kSplashIconsWidth;
	*height = kSplashIconsHeight;
}


status_t
video_splash_decode_logo(uint8* buffer, size_t size)
{
	if (size == (size_t)kSplashLogoWidth * kSplashLogoHeight * 3) {
		return uncompress(kSplashLogo24BitCompressedImage,
			sizeof(kSplashLogo24BitCompressedImage), buffer, size);
	}
	if (size == (size_t)kSplashLogoWidth * kSplashLogoHeight) {
		return uncompress(kSplashLogo8BitCompressedImage,
			sizeof(kSplashLogo8BitCompressedImage), buffer, size);
	}
	return B_BAD_VALUE;
}


status_t
video_splash_decode_icons(uint8* buffer, size_t size)
{
	if (size == (size_t)kSplashIconsWidth * kSplashIconsHeight * 3) {
		return uncompress(kSplashIcons24BitCompressedImage,
			sizeof(kSplashIcons24BitCompressedImage), buffer, size);
	}
	if (size == (size_t)kSplashIconsWidth * kSplashIconsHeight) {
		return uncompress(kSplashIcons8BitCompressedImage,
			sizeof(kSplashIcons8BitCompressedImage), buffer, size);
	}
	return B_BAD_VALUE;
}


status_t
video_display_splash(const splash_frame_buffer& frameBuffer, uint8** _icons)
{
	if (frameBuffer.frame_buffer == NULL || _icons == NULL)
		return B_NO_INIT;
	if (frameBuffer.depth == 4)
		return B_NOT_SUPPORTED;

	*_icons = NULL;

	// Clear the visible area. The boot loader estimated it from the mode
	// because UEFI can report a huge frame buffer; here the mapping size is
	// known, and the stride may be wider than width * 4.
	memset(frameBuffer.frame_buffer, 0,
		min_c((size_t)frameBuffer.bytes_per_row * frameBuffer.height,
			frameBuffer.size));

	uint8* uncompressedLogo = NULL;
	unsigned int uncompressedSize = kSplashLogoWidth * kSplashLogoHeight;
	switch (frameBuffer.depth) {
		case 8:
			if (video_set_palette != NULL)
				video_set_palette(k8BitPalette);
			uncompressedLogo = (uint8*)malloc(uncompressedSize);
			if (uncompressedLogo == NULL)
				return B_NO_MEMORY;

			uncompress(kSplashLogo8BitCompressedImage,
				sizeof(kSplashLogo8BitCompressedImage), uncompressedLogo,
				uncompressedSize);
		break;
		default: // 24 bits is assumed here
			uncompressedSize *= 3;
			uncompressedLogo = (uint8*)malloc(uncompressedSize);
			if (uncompressedLogo == NULL)
				return B_NO_MEMORY;

			uncompress(kSplashLogo24BitCompressedImage,
				sizeof(kSplashLogo24BitCompressedImage), uncompressedLogo,
				uncompressedSize);
		break;
	}

	// render splash logo
	int width, height, x, y;
	compute_splash_logo_placement(frameBuffer.width, frameBuffer.height,
		width, height, x, y);
	video_blit_image(frameBuffer, uncompressedLogo, width, height,
		kSplashLogoWidth, x, y);

	free(uncompressedLogo);

	// The boot loader put the icons in kernel_args (boot_splash) for the
	// kernel; the caller hands them to boot_splash_init() instead.
	uint8* icons;
	const uint8* lowerHalfIconImage;
	uncompressedSize = kSplashIconsWidth * kSplashIconsHeight;
	const uint16 iconsHalfHeight = kSplashIconsHeight / 2;
	switch (frameBuffer.depth) {
		case 8:
			// pointer into the lower half of the icons image data
			icons = (uint8*)malloc(uncompressedSize);
			if (icons == NULL)
				return B_NO_MEMORY;
			uncompress(kSplashIcons8BitCompressedImage,
				sizeof(kSplashIcons8BitCompressedImage),
				icons, uncompressedSize);
			lowerHalfIconImage = icons
				+ (kSplashIconsWidth * iconsHalfHeight);
		break;
		default:	// 24bits is assumed here
			uncompressedSize *= 3;
			// pointer into the lower half of the icons image data
			icons = (uint8*)malloc(uncompressedSize);
			if (icons == NULL)
				return B_NO_MEMORY;
			uncompress(kSplashIcons24BitCompressedImage,
				sizeof(kSplashIcons24BitCompressedImage),
				icons, uncompressedSize);
			lowerHalfIconImage = icons
				+ (kSplashIconsWidth * iconsHalfHeight) * 3;
		break;
	}

	// render initial (grayed out) icons
	// the grayed out version is the lower half of the icons image
	compute_splash_icons_placement(frameBuffer.width, frameBuffer.height,
		width, height, x, y);

	video_blit_image(frameBuffer, lowerHalfIconImage, width, height,
		kSplashIconsWidth, x, y);

	*_icons = icons;
	return B_OK;
}
